def is_valid_fraction(numerator, denominator):
    return numerator != 0 and denominator != 0 and numerator % denominator == 0

def is_valid_fractions(fractions):
    for fraction in fractions:
        numerator, denominator = fraction
        if not is_valid_fraction(numerator, denominator):
            return False
    return True

def is_sum_of_fractions(fractions):
    total = sum(fractions)
    return total == 1

def find_valid_fractions():
    valid_fractions = []
    for numerator1 in range(1, 10):
